CREATE DATABASE IF NOT EXISTS pti_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE pti_db;
CREATE TABLE IF NOT EXISTS user (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(180) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'editor', is_active_account BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS category (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, slug VARCHAR(120) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS academic_program (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, description TEXT NOT NULL, icon VARCHAR(80) DEFAULT 'bi-mortarboard', is_published BOOLEAN NOT NULL DEFAULT TRUE, sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS lecturer (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(160) NOT NULL, academic_title VARCHAR(100) DEFAULT '', expertise VARCHAR(220) DEFAULT '', email VARCHAR(180) DEFAULT '', photo VARCHAR(255), bio TEXT, is_published BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS article (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(220) NOT NULL, slug VARCHAR(240) NOT NULL UNIQUE, excerpt VARCHAR(500) NOT NULL DEFAULT '', body LONGTEXT NOT NULL, cover_image VARCHAR(255), status VARCHAR(20) NOT NULL DEFAULT 'draft', category_id INT NULL, author_id INT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, published_at DATETIME NULL, INDEX ix_article_status (status), CONSTRAINT fk_article_category FOREIGN KEY (category_id) REFERENCES category(id) ON DELETE SET NULL, CONSTRAINT fk_article_author FOREIGN KEY (author_id) REFERENCES user(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS site_setting (id INT AUTO_INCREMENT PRIMARY KEY, `key` VARCHAR(100) NOT NULL UNIQUE, value TEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS contact_message (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(180) NOT NULL, subject VARCHAR(180) NOT NULL, message TEXT NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
